'use client'

import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import type { NavGroup, NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface AppSidebarProps {
  navGroups: NavGroup[]
  plan: PlanTier
  user: {
    name: string
    email: string
    avatarUrl?: string | null
  }
  studioName: string
  studioLogoUrl?: string | null
  role: NavRole
}

export function AppSidebar({
  navGroups,
  plan,
  user,
  studioName,
  studioLogoUrl,
  role,
}: AppSidebarProps) {
  return (
    <Sidebar collapsible="icon">
      <SidebarHeader className="px-4 py-4">
        <div className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-7 w-7 rounded object-cover"
            />
          ) : (
            <div className="flex h-7 w-7 items-center justify-center rounded bg-primary">
              <span className="text-[10px] font-bold text-primary-foreground">
                IO
              </span>
            </div>
          )}
          <div className="flex min-w-0 flex-col group-data-[collapsible=icon]:hidden">
            <span className="text-sm font-semibold leading-tight tracking-tight">
              InkOS
            </span>
            <span className="max-w-[140px] truncate text-xs text-muted-foreground">
              {studioName}
            </span>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent>
        {navGroups.map((group) => (
          <SidebarNavGroup key={group.label} group={group} plan={plan} />
        ))}
      </SidebarContent>

      <SidebarUserFooter user={user} studioName={studioName} role={role} />
    </Sidebar>
  )
}

