import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { OnboardingWizard } from '@/components/onboarding/OnboardingWizard'

export const metadata: Metadata = {
  title: 'Set up your studio',
}

export default async function OnboardingPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  // If studio already has a location → onboarding complete → go to dashboard
  const memberResult = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  const studioId = memberResult.data?.studio_id ?? null

  if (studioId) {
    const locResult = await supabase
      .from('locations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)

    if ((locResult.count ?? 0) > 0) {
      redirect('/dashboard')
    }
  }

  return (
    <div className="w-full max-w-[520px]">
      <OnboardingWizard studioId={studioId} userId={user.id} />
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { CheckCircle2, Copy, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'

interface StepBookingPageLiveProps {
  studioId: string | null
  startTime: number
  onBack: () => void
}

export function StepBookingPageLive({
  studioId,
  startTime,
  onBack,
}: StepBookingPageLiveProps) {
  const router = useRouter()
  const supabase = createClient()
  const [slug, setSlug] = useState<string | null>(null)

  useEffect(() => {
    if (!studioId) return

    supabase
      .from('studios')
      .select('slug')
      .eq('id', studioId)
      .single()
      .then(({ data }) => {
        if (data?.slug) setSlug(data.slug)
      })

    // Fire PostHog event
    const durationSeconds = Math.round((Date.now() - startTime) / 1000)
    if (typeof window !== 'undefined' && 'posthog' in window) {
      // @ts-expect-error — posthog is loaded via script tag
      window.posthog?.capture?.('onboarding_completed', {
        studioId,
        stepsCompleted: 5,
        duration_seconds: durationSeconds,
      })
    }

    // Clear onboarding step from localStorage — they're done
    localStorage.removeItem('inkos-onboarding-step')
  }, [studioId, startTime, supabase])

  const bookingUrl = slug ? `book.inkos.app/${slug}` : 'Generating...'

  function handleCopy() {
    if (!slug) return
    navigator.clipboard
      .writeText(`https://${bookingUrl}`)
      .then(() => toast.success('Link copied to clipboard'))
      .catch(() => toast.error('Could not copy to clipboard'))
  }

  function handleGoToDashboard() {
    router.push('/dashboard')
    router.refresh()
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col items-center text-center">
        <CheckCircle2
          className="mb-4 h-14 w-14 text-primary"
          style={{ filter: 'drop-shadow(0 0 20px oklch(72% 0.28 292 / 0.4))' }}
          aria-hidden="true"
        />
        <h2 className="text-xl font-bold tracking-tight">
          Your studio is live
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Clients can now book online
        </p>
      </div>

      {/* Booking link */}
      <div className="rounded-lg bg-muted/30 p-4">
        <p className="mb-1 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">
          Your booking link
        </p>
        <p className="mb-3 font-mono text-sm text-foreground">{bookingUrl}</p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopy}
            disabled={!slug}
          >
            <Copy className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
            Copy link
          </Button>
          {slug && (
            <Button
              variant="outline"
              size="sm"
              render={
                <a
                  href={`https://${bookingUrl}`}
                  target="_blank"
                  rel="noopener noreferrer"
                />
              }
            >
              <ExternalLink className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
              Open preview
            </Button>
          )}
        </div>
      </div>

      {/* What's next */}
      <div>
        <p className="mb-3 text-sm font-medium">What&#39;s next:</p>
        <ul className="space-y-2">
          {[
            'Invite your team',
            'Add more services',
            'Connect Google Calendar',
          ].map((item) => (
            <li key={item} className="flex items-center gap-2 text-sm text-muted-foreground">
              <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground/40" aria-hidden="true" />
              {item}
            </li>
          ))}
        </ul>
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <Button onClick={handleGoToDashboard} className="w-full max-w-[200px]">
          Go to dashboard →
        </Button>
      </div>
    </div>
  )
}

